{
  "catalog_version": 1,
  "harness": "codex",
  "runtime_files": ["shared/schemas"],
  "plugins": [
    {
      "id": "courier",
      "category": "ship",
      "default_prompt": "Turn verified work into a reviewable commit, PR, changeset, review response, or release artifact.",
      "capabilities": ["skills", "agent-teams-optional"],
      "skills": {
        "changeset": {"team_mode": "optional", "prompt": "Read the actual diff and linked criteria evidence; split independent topics. For each topic, classify consumer and semver impact, then emit one `changeset@2` matching `shared/schemas/changeset@2.json`; do not bundle unrelated work or rewrite a prior entry."},
        "commit": {"team_mode": "optional", "prompt": "Read only the staged diff and prepare a conventional commit message that explains why the verified change exists. Show the exact message and staged scope before creating a commit; create it only after the user confirms."},
        "post-review": {"team_mode": "never", "prompt": "This is mechanical delivery, not review authorship. Require already-drafted text and its precise PR/thread target, show both verbatim, and post or resolve nothing until the user explicitly confirms the external action."},
        "pr": {"team_mode": "optional", "prompt": "Ground the title and reviewer-oriented body in the actual diff, linked requirement/spec, and tests. Include scope, evidence, and remaining risks; show the exact title, body, labels, and target before `gh pr create`, then wait for explicit confirmation."},
        "receive-feedback": {"team_mode": "optional", "prompt": "Assemble a neutral response package from the PR diff, linked artifacts, test results, comments, and open questions. Preserve evidence and uncertainty; do not invent priority or accept/reject review feedback for the user."},
        "release": {"team_mode": "optional", "prompt": "Validate each input against `shared/schemas/changeset@2.json`, exclude `internal-only` entries, compute the largest remaining semver bump from the prior version, and carry approved summaries forward unedited in `release-artifact@2`. Report the inputs and version calculation."}
      }
    },
    {
      "id": "mason",
      "category": "meta",
      "default_prompt": "Build or audit a conformant plugin, native skill, agent, or versioned handoff contract.",
      "capabilities": ["skills", "agent-teams-optional"],
      "skills": {
        "audit-plugin": {"team_mode": "optional", "prompt": "Inspect the named plugin rather than assuming its shape. Check manifest declarations against files, skill frontmatter, agent structure, shared contracts, and constitution requirements; return a path-specific pass/fail/warn report with evidence and repair guidance."},
        "design-schema": {"team_mode": "optional", "prompt": "Identify producer, consumer, durable fields, and failure modes before drafting. Produce a Draft 2020-12 schema at `shared/schemas/<name>@<version>.json` with `$id`, documented fields, `additionalProperties: false`, and a `reasoning` scratchpad; check existing contracts for collisions first."},
        "scaffold-plugin": {"team_mode": "optional", "prompt": "Turn the supplied purpose into a complete, installable plugin: manifest, skill routes, cognitive-mode agents, README, changelog, and registered marketplace entry. Reuse the shared constitution byte-for-byte where required, define handoff schemas before prompts, and validate the resulting tree rather than leaving stubs or TODOs."},
        "scaffold-subagent": {"team_mode": "optional", "prompt": "Add exactly one agent to the existing plugin without changing unrelated routes. Inspect the live plugin first, choose the requested cognitive mode and tier, preserve the shared constitution prefix exactly, and return the new path plus the dispatch wiring still needed, if any."}
      }
    },
    {
      "id": "muse",
      "category": "design",
      "default_prompt": "Turn UI or component intent and repository evidence into a testable spec@1. Persist a passing spec at docs/specs/<id>.json; use an agent team only for independent design and accessibility review, with a complete single-agent fallback.",
      "capabilities": ["skills", "agent-teams-optional"],
      "skills": {
        "component": {"team_mode": "optional", "prompt": "Read the supplied UI intent, existing component API, and accessibility evidence. Produce a testable spec@1 conforming to shared/schemas/spec@1.json and its verdict@1; after a pass, persist it at docs/specs/<id>.json with spec_file_path set. If agent teams are available, independently review behavior and accessibility; otherwise perform both passes yourself."}
      }
    },
    {
      "id": "navigator",
      "category": "build",
      "default_prompt": "Read the persisted spec@1 and live APIs, then create an executable plan@1 at docs/projects/<linked_spec>.json. Teams may independently challenge plan coverage; the single-agent path must still verify every criterion.",
      "capabilities": ["skills", "agent-teams-optional"],
      "skills": {
        "plan": {"team_mode": "optional", "prompt": "Read spec_file_path when set, inspect the live API surface, and preserve its raw-byte spec_hash. Produce plan@1 conforming to shared/schemas/plan@1.json, with each criterion covered by an implementation and proving test; persist it at docs/projects/<linked_spec>.json with plan_file_path set. If teams are available, use an independent plan challenge; otherwise challenge the plan before returning it."}
      }
    },
    {
      "id": "ranger",
      "category": "verify",
      "default_prompt": "Find evidence-backed, reachable defects and distinguish them from signals that do not survive review.",
      "capabilities": ["skills", "agent-teams-optional"],
      "skills": {
        "audit": {"team_mode": "optional", "prompt": "Start with a live-file and entry-point manifest, then load only the relevant language hazard taxonomy. Trace each candidate through control flow, using boundary tracing for T7/T10 when applicable; report only reachable confirmed defects with a concrete failing scenario, retain unresolved reachability as plausible, and emit `finding-report@1` plus `verdict@2` evidence. Never report dead or unreachable code as a bug."}
      }
    },
    {
      "id": "scribe",
      "category": "design",
      "default_prompt": "Use requirements, research, live code, and persisted artifacts to create or verify a durable spec@1. Persist only gated specs at docs/specs/<id>.json; teams may split independent evidence or adversarial review, while the single-agent path remains complete.",
      "capabilities": ["skills", "agent-teams-optional"],
      "skills": {
        "architect": {"team_mode": "optional", "prompt": "Use finding-report@1, live code, and existing contracts as evidence for an architecture-backed spec@1 or arch-spec@1. Conform to shared/schemas/spec@1.json or shared/schemas/arch-spec@1.json; route the draft through verification and gate it before persistence at docs/specs/<id>.json. If teams are available, partition independent architectural evidence; otherwise perform the synthesis and challenge yourself."},
        "audit-architecture": {"team_mode": "optional", "prompt": "Read the candidate spec@1 and docs/architecture/model.json when present. Produce arch-audit@1 under shared/schemas/arch-audit@1.json; in build mode validate and overwrite the durable arch-model@1 at docs/architecture/model.json using shared/schemas/arch-model@1.json. Teams may independently inspect architectural boundaries; otherwise complete the audit alone."},
        "audit-spec": {"team_mode": "optional", "prompt": "Read the candidate spec@1, its requirement/research evidence, and any persisted source paths. Return a concrete adversarial issue report and pass/fail recommendation against shared/schemas/spec@1.json; do not persist a new artifact. If teams are available, use one independent skeptical review; otherwise conduct that review yourself."},
        "correct-spec": {"team_mode": "optional", "prompt": "Read spec_file_path, the named criterion, and observed contradiction evidence. Amend the existing spec@1 under shared/schemas/spec@1.json, retain its durable path at docs/specs/<id>.json, set revision_note, then send it through verify, audit, and gate. Teams may independently test the contradiction; otherwise validate it yourself."},
        "draft-spec": {"team_mode": "optional", "prompt": "Use requirement@1, optional research-report@1, and inspected live APIs as evidence. Produce a testable draft spec@1 conforming to shared/schemas/spec@1.json; do not persist it until gate-spec passes, then use docs/specs/<id>.json. If teams are available, split research/API evidence from drafting; otherwise complete both yourself."},
        "gate-spec": {"team_mode": "optional", "prompt": "Read the post-verification, post-audit spec@1 and only the required blocker evidence. Return verdict@1 under shared/schemas/verdict@1.json; on pass, persist the exact spec bytes at docs/specs/<id>.json and set spec_file_path, and on fail return blockers for correction. Teams may independently re-check blocking evidence; otherwise make the binding decision alone."},
        "spec-drift": {"team_mode": "optional", "prompt": "Read the persisted spec from spec_file_path, inspect current implementation evidence, and report covered, uncovered, and drifted criteria against shared/schemas/spec@1.json. Keep docs/specs/<id>.json read-only; the output is a cited drift report, not a new durable artifact. If teams are available, partition criterion evidence; otherwise trace it yourself."},
        "verify-spec": {"team_mode": "optional", "prompt": "Read the draft spec@1, originating requirement@1, optional research-report@1, and live API evidence. Return per-criterion supported, unsupported, or overfitted evidence against shared/schemas/spec@1.json; do not persist until gate-spec passes at docs/specs/<id>.json. If teams are available, split independent evidence checks; otherwise verify all criteria yourself."}
      }
    },
    {
      "id": "sentinel",
      "category": "verify",
      "default_prompt": "Independently verify a stage artifact against its criteria before it crosses a lifecycle boundary.",
      "capabilities": ["skills", "agent-teams-optional"],
      "skills": {
        "gate": {"team_mode": "optional", "prompt": "Identify the artifact, its persisted path, and every applicable criterion before judging it. Re-read the cited source and implementation, classify each criterion as verified, failed, or unverifiable, then emit a `verdict@1` using `shared/schemas/verdict@1.json`; pass only when all criteria are verified, otherwise return specific actionable blockers. Retry only against the prior blockers and escalate after the third failed retry."}
      }
    },
    {
      "id": "smith",
      "category": "build",
      "default_prompt": "Execute a persisted plan in bounded batches and prove every acceptance criterion with real evidence.",
      "capabilities": ["skills", "agent-teams-optional"],
      "skills": {
        "implement": {"team_mode": "optional", "prompt": "Read `plan@1` and its `spec_file_path` from disk; execute one coherent subsystem batch at a time. Design before changing code, implement only the planned scope, write tests that prove every `covers_criteria` item, run the full suite, and retain exact `criteria_evidence` pointers. Run mutation testing when available and record a coverage gap when it is not; halt and route a `spec_contradiction` or unsafe architectural shape instead of guessing. Finish with independent `verdict@1` verification, not self-certification."}
      }
    },
    {
      "id": "vanguard",
      "category": "define",
      "default_prompt": "Research a requirement with cited internal and external evidence, then persist research-report@1 at docs/research/<id>.json. Teams may divide independent evidence collection, but one agent must synthesize a complete report when teams are unavailable.",
      "capabilities": ["skills", "agent-teams-optional"],
      "skills": {
        "research": {"team_mode": "optional", "prompt": "Read the supplied requirement@1 and map relevant code, docs, dependencies, and external sources before drawing conclusions. Produce research-report@1 conforming to shared/schemas/research-report@1.json, distinguish findings from assumptions, and persist it at docs/research/<id>.json. If teams are available, collect independent evidence in parallel then synthesize it; otherwise perform mapping, reading, risk review, and synthesis yourself."}
      }
    },
    {
      "id": "weaver",
      "category": "define",
      "default_prompt": "Turn product evidence into durable requirement@1 artifacts at docs/requirements/<id>.json, or audit those artifacts read-only. Teams may parallelize independent evidence gathering; every action retains a complete single-agent fallback.",
      "capabilities": ["skills", "agent-teams-optional"],
      "skills": {
        "audit-backlog": {"team_mode": "optional", "prompt": "Read all relevant requirement@1 files from docs/requirements/ and workspace evidence. Return a cited, read-only backlog health report identifying incomplete, duplicate, or stale requirements under shared/schemas/requirement@1.json; do not modify durable artifacts. If teams are available, partition the backlog; otherwise audit it yourself."},
        "capture-need": {"team_mode": "optional", "prompt": "Use the supplied need statement and available tracker or workspace evidence to draft requirement@1 under shared/schemas/requirement@1.json. Persist the durable draft at docs/requirements/<id>.json, recording uncertainties in reasoning and routing gaps to clarification. If teams are available, gather independent evidence; otherwise capture it yourself."},
        "clarify-requirement": {"team_mode": "optional", "prompt": "Read the durable requirement@1 at docs/requirements/<id>.json and its stated evidence. Ask one decision-closing question at a time; after each answer, update the same file under shared/schemas/requirement@1.json until ready for Scribe. Teams may independently surface ambiguities, but the single-agent path must resolve them sequentially."},
        "connect-requirement": {"team_mode": "optional", "prompt": "Read the selected requirement@1 files in docs/requirements/ plus tracker and workspace evidence. Return a cited status, relationship, and duplicate assessment without modifying the requirement JSON; evaluate it against shared/schemas/requirement@1.json. If teams are available, investigate independent relationships; otherwise trace them yourself."},
        "prioritize-backlog": {"team_mode": "optional", "prompt": "Read the candidate requirement@1 artifacts from docs/requirements/ and supplied product constraints. Return a ranked, cited list of requirement IDs, rationale, and dependencies; preserve the source JSON under shared/schemas/requirement@1.json without mutation. If teams are available, independently score groups then reconcile; otherwise rank the backlog yourself."}
      }
    }
  ]
}

